create or replace function public.cineo_review_month(actor uuid,owner uuid,period date,approved bigint,note text) returns jsonb language plpgsql security invoker set search_path='' as $$declare n bigint;gross bigint;result_id uuid;begin
 if not exists(select 1 from public.cineo_admins where user_id=actor) then raise exception 'Acesso restrito';end if;
 perform 1 from public.cineo_creator_accounts where user_id=owner for update;if not found then raise exception 'Cadastro de criador inexistente';end if;
 if period<>date_trunc('month',period)::date or period>=date_trunc('month',now() at time zone 'America/Sao_Paulo')::date or length(trim(note))<5 then raise exception 'Revise um mês encerrado e informe o parecer';end if;
 if exists(select 1 from public.cineo_copyright_cases where creator_id=owner and status='reviewing') then raise exception 'Há uma investigação de direitos em andamento';end if;
 select count(*) into n from public.cineo_qualified_views where creator_id=owner and day>=period and day<(period+interval '1 month')::date;
 select floor(coalesce(sum(rate_cents_per_thousand) filter(where day<(period+interval '1 month')::date),0)/1000.0)-floor(coalesce(sum(rate_cents_per_thousand) filter(where day<period),0)/1000.0) into gross from public.cineo_qualified_views where creator_id=owner;
 if approved<0 or approved>gross then raise exception 'O valor aprovado excede a estimativa do mês';end if;
 insert into public.cineo_monthly_settlements(creator_id,month,views,gross_cents,approved_cents,reason,reviewed_by) values(owner,period,n,gross,approved,left(note,2000),actor) returning id into result_id;
 insert into public.cineo_studio_audit(creator_id,actor_id,action,detail) values(owner,actor,'month_closed',jsonb_build_object('id',result_id,'month',period,'gross_cents',gross,'approved_cents',approved,'reason',left(note,2000)));
 return jsonb_build_object('id',result_id,'gross_cents',gross,'approved_cents',approved);
end$$;

create or replace function public.cineo_studio_finance(owner uuid) returns jsonb language sql stable security invoker set search_path='' as $$with totals as(select date_trunc('month',day)::date as month,count(*) views,sum(rate_cents_per_thousand) units from public.cineo_qualified_views where creator_id=owner group by 1),monthly as(select month,views,floor(sum(units) over(order by month)/1000.0)-floor((sum(units) over(order by month)-units)/1000.0) gross_cents from totals) select jsonb_build_object('rules',(select to_jsonb(r) from public.cineo_payout_rules r where id=1),'available_cents',coalesce((select sum(approved_cents) from public.cineo_monthly_settlements where creator_id=owner),0)-coalesce((select sum(amount_cents) from public.cineo_withdrawals where creator_id=owner and status in('requested','approved','paid')),0),'months',(select coalesce(jsonb_agg(x order by month desc),'[]') from monthly x),'settlements',(select coalesce(jsonb_agg(s order by month desc),'[]') from public.cineo_monthly_settlements s where creator_id=owner),'withdrawals',(select coalesce(jsonb_agg(x order by created_at desc),'[]') from(select id,amount_cents,pix_hint,status,note,payment_reference,created_at from public.cineo_withdrawals where creator_id=owner order by created_at desc limit 100)x))$$;

create or replace function public.cineo_reviewable_months() returns jsonb language sql stable security invoker set search_path='' as $$with totals as(select creator_id,date_trunc('month',day)::date as month,count(*) views,sum(rate_cents_per_thousand) units from public.cineo_qualified_views group by 1,2),monthly as(select creator_id,month,views,floor(sum(units) over(partition by creator_id order by month)/1000.0)-floor((sum(units) over(partition by creator_id order by month)-units)/1000.0) gross_cents from totals) select coalesce(jsonb_agg(x order by month desc),'[]') from(select m.*,p.name creator_name from monthly m left join public.cineo_profiles p on p.user_id=m.creator_id where m.month<date_trunc('month',now() at time zone 'America/Sao_Paulo')::date and not exists(select 1 from public.cineo_monthly_settlements s where s.creator_id=m.creator_id and s.month=m.month) order by m.month desc limit 100)x$$;
